import{newEvent}from'./event-model.js';
import{wrapDialogue}from'./world-model.js';
import{gateLocal}from'./gate-cells.js';
import{gameContext}from'./game-runtime.js';
import{editsFor}from'./game-edits.js';
import{studioData,spriteId}from'./sprite-workbench.js';
import{creatureDefaults,validateCreature,formRecord,ABILITY_TRIGGERS,ABILITY_CONDITIONS,ABILITY_EFFECTS}from'./creature-model.js';
import{readFormDonor,encodeCreatureText,EXPANDED_TYPE_NAMES}from'./expanded-form-native.js';
export function creatureWorkshop(api){
 const $=s=>document.querySelector(s),esc=api.esc,state={context:null,groupId:null};
 const groups=()=>studioData(api.project()).groups.filter(g=>g.kind==='pokemon');
 const group=()=>groups().find(g=>g.id===state.groupId);
 const edits=()=>state.context?editsFor(api.project(),state.context.hash):null;
 const profile=()=>state.context?.forms;
 const names=()=>[...(profile()?.species||state.context?.data?.species||[]),...(edits()?.forms||[]).map(f=>({id:f.slot,name:f.name}))];
 const textChoice=(id,label,list,value)=>`<label>${esc(label)}<input id="${id}" list="${id}Options" value="${esc(list.find(n=>n.id===value)?.name||'')} (#${value||0})"><datalist id="${id}Options">${list.map(n=>`<option value="${esc(n.name)} (#${n.id})"></option>`).join('')}</datalist></label>`;
 const parse=(id,list)=>{const t=$('#'+id).value,m=t.match(/\(#(\d+)\)$/),n=m?+m[1]:/^\d+$/.test(t)?+t:list.find(n=>n.name.toLowerCase()===t.toLowerCase())?.id;if(!list.some(e=>e.id===n))throw Error('Choose a named Pokémon from the list.');return n;};
 const number=(id,label,value,min,max)=>`<label>${esc(label)}<input id="${id}" type="number" min="${min}" max="${max}" value="${value}"></label>`;
 const select=(id,label,values,value)=>`<label>${esc(label)}<select id="${id}">${values.map((n,i)=>`<option value="${i}" ${i===value?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`;
 function changed(fn){api.change(fn);api.refresh();}
 async function open(id=null){try{state.context=api.session()?await gameContext(api.session().reader):null;state.groupId=id||state.groupId;if(group()){const g=group(),c=creatureDefaults(g);if(!c.parent&&profile()&&g.source?.hash===state.context.hash){try{const d=readFormDonor(state.context.reader.bytes,profile(),g.source.species);Object.assign(c,{parent:d.id,stats:d.stats,types:d.types,abilities:d.abilities,description:d.dexText,category:'regional',dexCategory:d.category,catchRate:d.catchRate,friendship:d.friendship,baseExp:d.baseExp,height:d.height,weight:d.weight,learnset:d.learnset||[],evolutions:[]});}catch{}}edit();}else browser();}catch(e){api.error(e);}}
 function browser(){const p=profile(),queued=edits()?.forms||[];api.modal('Pokémon & forms',`<p>Create a Pokémon group with front, back, menu and walking sprites, paired normal/shiny palettes and its game data.</p>${p?`<p class="callout"><b>${esc(p.name)}</b><br>${p.blankSlots.length-queued.length} verified empty species records available. New native forms have their own species ID, stats, art and evolutions. They share their parent’s Pokédex number and seen/caught flags.</p>`:'<p class="callout">Creature designs and sprite exports work with any project. Installing new native forms is verified for the supplied Heart and Soul 2.0.6 and Team Rocket Edition 3.04 ROMs. Other engines need a matching adapter.</p>'}<div class="smart-actions"><button id="creatureNew" type="button" class="primary">＋ New Pokémon group</button><button id="creatureClone" type="button">Use a ROM Pokémon as template</button><button id="creatureROM" type="button">${state.context?'Change ROM':'Open ROM'}</button></div><div class="creature-cards">${groups().map(g=>`<article><b>${esc(g.name)}</b><span>${esc(g.creature?.category||'new')} · ${Object.keys(g.views).length} sprite views</span><button data-creature="${g.id}" type="button">Edit Pokémon</button><button data-creature-sprite="${g.id}" type="button">Sprites</button></article>`).join('')||'<p>No custom Pokémon yet. Duplicate an actual ROM sprite group or start a new one.</p>'}</div>${queued.length?`<h3>Included in the next ROM export</h3>${queued.map(f=>`<div class="game-data-row"><span>${esc(f.name)} · species ${f.slot}</span><button data-form-remove="${f.slot}" type="button">Remove from ROM export</button></div>`).join('')}`:''}`);$('#creatureNew').onclick=()=>api.sprites().newGroupDialog();$('#creatureClone').onclick=async()=>{try{if(!api.session()){api.pickROM('sprites');return;}await api.sprites().open({kind:'mon',id:1,side:'front'});api.toast('Find your Pokémon, then tap Duplicate group.');}catch(e){api.error(e);}};$('#creatureROM').onclick=()=>api.pickROM('game');document.querySelectorAll('[data-creature]').forEach(b=>b.onclick=()=>{state.groupId=b.dataset.creature;edit();});document.querySelectorAll('[data-creature-sprite]').forEach(b=>b.onclick=()=>api.sprites().open({kind:'custom',id:b.dataset.creatureSprite}));document.querySelectorAll('[data-form-remove]').forEach(b=>b.onclick=()=>{changed(()=>{const old=edits().forms.find(f=>f.slot===+b.dataset.formRemove);edits().forms=edits().forms.filter(f=>f.slot!==+b.dataset.formRemove);for(const m of api.project().maps)for(const n of m.markers)if(n.creatureGift?.groupId===old?.groupId)n.runtime.enabled=false;});api.toast('Form removed from export; its gift events are disabled.');browser();});}
 function edit(){const g=group();if(!g){browser();return;}const c=structuredClone(creatureDefaults(g)),p=profile(),list=names(),abilities=p?.abilities||[],queued=edits()?.forms?.find(f=>f.groupId===g.id);api.modal('Pokémon · '+g.name,`<label>Group name<input id="creatureName" maxlength="80" value="${esc(g.name)}"></label><label>Design<select id="creatureKind">${[['new','New Pokémon'],['regional','Regional form'],['alternate','Alternate form'],['evolution','New evolution']].map(([id,n])=>`<option value="${id}" ${c.category===id?'selected':''}>${n}</option>`).join('')}</select></label>${list.length?textChoice('creatureParent','Native parent / template',list,c.parent||1):number('creatureParentId','Parent species ID (optional)',c.parent||0,0,8191)}${p?'<button id="creatureInherit" type="button">Use parent’s stats, abilities & dex text</button>':''}<details open><summary>Identity & Pokédex</summary><div class="field-row"><label>In-game name<input id="creatureNativeName" maxlength="12" value="${esc(c.nativeName)}"></label><label>Dex category<input id="creatureDexCategory" maxlength="12" value="${esc(c.dexCategory)}"></label></div><label>Dex entry<textarea id="creatureDex" maxlength="2048" rows="5">${esc(c.description)}</textarea></label><div class="field-row">${number('creatureHeight','Height (decimetres)',c.height,0,65535)}${number('creatureWeight','Weight (hectograms)',c.weight,0,65535)}</div></details><details open><summary>Types & base stats</summary><div class="field-row">${select('creatureType0','First type',EXPANDED_TYPE_NAMES,c.types[0])}${select('creatureType1','Second type',EXPANDED_TYPE_NAMES,c.types[1])}</div><div class="creature-stats">${['HP','Attack','Defence','Speed','Sp. Attack','Sp. Defence'].map((n,i)=>number('creatureStat'+i,n,c.stats[i],1,255)).join('')}</div><p id="creatureBST"></p></details><details><summary>Abilities & other stats</summary><p>Choose existing native ability mechanics. Custom ability rules are designed below and exported for engine integration.</p>${c.abilities.map((v,i)=>abilities.length?`<label>${['Ability 1','Ability 2','Hidden ability'][i]}<select id="creatureAbility${i}">${abilities.map(a=>`<option value="${a.id}" ${v===a.id?'selected':''}>${esc(a.name)} · ${a.id}</option>`).join('')}</select></label>`:number('creatureAbility'+i,['Ability 1 ID','Ability 2 ID','Hidden ability ID'][i],v,0,1023)).join('')}<div class="field-row">${number('creatureCatch','Catch rate',c.catchRate,0,255)}${number('creatureExp','Base experience',c.baseExp,0,65535)}${number('creatureFriend','Base friendship',c.friendship,0,255)}</div></details><div class="smart-actions"><button id="creatureSprites" type="button">Paint sprites & clothing</button><button id="creatureMoves" type="button">Level-up moves · ${c.learnset.length}</button><button id="creatureEvos" type="button">Evolutions · ${c.evolutions.length}</button><button id="creatureAbilities" type="button">Custom ability designer</button></div><p>${p?'Native installation creates a distinct form in a verified empty record. Its Pokédex number and seen/caught flags remain shared with the parent. '+(queued?'Queued as species '+queued.slot+'.':''):'This design can be exported with its sprite group. Native new-form installation needs one of the verified expansion ROMs.'}</p><div class="smart-actions"><button id="creatureInstall" type="button" class="primary" ${!p?'disabled':''}>${queued?'Update queued native form':'Add native form to ROM export'}</button>${queued?'<button id="creatureGift" type="button">Place a gift of this form</button>':''}<button id="creatureExport" type="button">Export Pokémon design</button><button id="creatureList" type="button">All Pokémon groups</button></div><details><summary>What is saved?</summary><p>Sprite groups, indexed layers, palettes, reference pictures, game data and ability designs are saved in this project. A queued native form is compiled from the current sprite art each time you export a ROM.</p><p>Custom ability designs are exportable rules. They do not install new battle code. New national Pokédex numbers and engine-wide species expansion need engine support.</p></details>`,()=>{collect();commit();},'Save Pokémon');
 function collect(){c.category=$('#creatureKind').value;c.parent=list.length?parse('creatureParent',list):+$('#creatureParentId').value||null;c.nativeName=$('#creatureNativeName').value;c.dexCategory=$('#creatureDexCategory').value;c.description=$('#creatureDex').value;c.stats=c.stats.map((_,i)=>+$('#creatureStat'+i).value);c.types=[+$('#creatureType0').value,+$('#creatureType1').value];c.abilities=[0,1,2].map(i=>+$('#creatureAbility'+i).value);Object.assign(c,{height:+$('#creatureHeight').value,weight:+$('#creatureWeight').value,catchRate:+$('#creatureCatch').value,baseExp:+$('#creatureExp').value,friendship:+$('#creatureFriend').value});validateCreature(c);}
 function commit(){const name=$('#creatureName').value.trim()||g.name;changed(()=>{g.name=name;g.creature=structuredClone(c);const f=edits()?.forms?.find(f=>f.groupId===g.id);if(f)Object.assign(f,formRecord(g,f.slot));});}
 const act=fn=>()=>{try{collect();commit();fn();}catch(e){api.error(e);}};
 $('#creatureSprites').onclick=act(()=>api.sprites().open({kind:'custom',id:g.id}));$('#creatureMoves').onclick=act(()=>moves());$('#creatureEvos').onclick=act(()=>evolutions());$('#creatureAbilities').onclick=act(()=>abilityBrowser());$('#creatureInstall').onclick=act(()=>installation());if($('#creatureGift'))$('#creatureGift').onclick=act(()=>{api.mode('nativeGift');api.close();api.toast('Tap an empty interaction tile on this map.');});$('#creatureExport').onclick=act(()=>api.save(new Blob([JSON.stringify({format:'shattered-creature-1',name:g.name,creature:g.creature},null,2)],{type:'application/json'}),g.name.replace(/[^a-z0-9_-]/gi,'_')+'_Pokemon.json'));$('#creatureList').onclick=act(()=>browser());if($('#creatureInherit'))$('#creatureInherit').onclick=()=>{try{const d=readFormDonor(state.context.reader.bytes,p,parse('creatureParent',list));changed(()=>Object.assign(g.creature,{parent:d.id,stats:d.stats,types:d.types,abilities:d.abilities,description:d.dexText,dexCategory:d.category,height:d.height,weight:d.weight,catchRate:d.catchRate,friendship:d.friendship,baseExp:d.baseExp,learnset:d.learnset||[]}));edit();}catch(e){api.error(e);}};const bst=()=>$('#creatureBST').textContent='Base stat total: '+c.stats.reduce((n,_,i)=>n+(+$('#creatureStat'+i).value||0),0);for(let i=0;i<6;i++)$('#creatureStat'+i).oninput=bst;bst();}
 function saveCollection(key,value){changed(()=>{group().creature[key]=structuredClone(value);const f=edits()?.forms?.find(f=>f.groupId===group().id);if(f)Object.assign(f,formRecord(group(),f.slot));});}
 function moves(){const rows=structuredClone(group().creature.learnset);api.modal('Level-up moves · '+group().name,'<p>Moves use this engine’s IDs. Several moves can share a level. An empty list means this form learns no moves by level; Use parent’s data copies its native learnset.</p><div id="creatureMoveRows"></div><button id="creatureMoveAdd" type="button">＋ Move</button>',()=>{collect();rows.sort((a,b)=>a.level-b.level);saveCollection('learnset',rows);edit();return false;},'Save moves');function collect(){rows.forEach((r,i)=>Object.assign(r,{level:+$('#cmLevel'+i).value,move:profile()?.moves?.length?parse('cmMove'+i,profile().moves):+$('#cmMove'+i).value}));const c={...group().creature,learnset:rows};validateCreature(c);}function draw(){$('#creatureMoveRows').innerHTML=rows.map((r,i)=>`<div class="game-data-row">${number('cmLevel'+i,'Level',r.level,1,255)}${profile()?.moves?.length?textChoice('cmMove'+i,'Move',profile().moves,r.move):number('cmMove'+i,'Move ID',r.move,1,65534)}<button type="button" data-cm-remove="${i}">×</button></div>`).join('');document.querySelectorAll('[data-cm-remove]').forEach(b=>b.onclick=()=>{collect();rows.splice(+b.dataset.cmRemove,1);draw();});}draw();$('#creatureMoveAdd').onclick=()=>{try{collect();if(rows.length>=127)throw Error('Use up to 127 moves.');rows.push({level:rows.at(-1)?.level||1,move:1});draw();}catch(e){api.error(e);}};}
 function evolutions(){const rows=structuredClone(group().creature.evolutions),list=names();api.modal('Evolutions · '+group().name,'<p>Choose the next species or another queued custom form. Add the target form to the ROM export first so its species ID appears here. Regional evolutions keep their own distinct targets.</p><div id="creatureEvoRows"></div><button id="creatureEvoAdd" type="button">＋ Evolution</button>',()=>{collect();saveCollection('evolutions',rows);edit();return false;},'Save evolutions');function collect(){rows.forEach((r,i)=>Object.assign(r,{method:$('#ceMethod'+i).value,target:list.length?parse('ceTarget'+i,list):+$('#ceTarget'+i).value,param:+$('#ceParam'+i).value}));validateCreature({...group().creature,evolutions:rows});}function draw(){$('#creatureEvoRows').innerHTML=rows.map((r,i)=>`<article class="event-step"><label>Evolve when<select id="ceMethod${i}">${[['level','Reach a level'],['trade','Trade'],['item','Use an item']].map(([k,n])=>`<option value="${k}" ${r.method===k?'selected':''}>${n}</option>`).join('')}</select></label>${list.length?textChoice('ceTarget'+i,'Evolves into',list,r.target):number('ceTarget'+i,'Target species ID',r.target,1,8191)}${number('ceParam'+i,'Required level / item ID (0 for trade)',r.param,0,65535)}<button type="button" data-ce-remove="${i}">Remove branch</button></article>`).join('');document.querySelectorAll('[data-ce-remove]').forEach(b=>b.onclick=()=>{collect();rows.splice(+b.dataset.ceRemove,1);draw();});}draw();$('#creatureEvoAdd').onclick=()=>{try{collect();if(rows.length>=32)throw Error('Use up to 32 evolution branches.');rows.push({method:'level',target:list[0]?.id||1,param:16});draw();}catch(e){api.error(e);}};}
 function installation(){const g=group(),p=profile(),queued=edits()?.forms||[],old=queued.find(f=>f.groupId===g.id),slot=old?.slot??p?.blankSlots.find(id=>!queued.some(f=>f.slot===id));if(slot===undefined)throw Error('No verified empty native species records remain.');const f=formRecord(g,slot);encodeCreatureText(f.name,{max:12,field:'In-game name'});if(f.category)encodeCreatureText(f.category,{max:12,field:'Dex category'});encodeCreatureText(f.dexText,{max:2048,field:'Dex entry'});const donor=readFormDonor(state.context.reader.bytes,p,f.parent);api.modal('Add a native Pokémon form',`<p><b>${esc(f.name)}</b> will use unused species ID <b>${slot}</b> in ${esc(p.name)}.</p><p>It has its own name, stats, abilities, level-up moves, evolutions and normal/shiny art. It shares Pokédex #${donor.dexNumber} and seen/caught flags with ${esc(donor.name)}. Existing Pokémon are preserved.</p><p>Front, back and menu art use the group’s current frames and palettes. Artwork is fitted with nearest-pixel scaling to the parent’s native dimensions; extra native animation frames repeat the last supplied frame. Walking art is installed when the parent has a supported overworld group.</p><p>Custom ability designs remain exportable designs; select existing native abilities for this playable form. After installation, use Place a gift of this form and tap a map tile to receive it during playtesting.</p>`,()=>{changed(()=>{const e=editsFor(api.project(),state.context.hash,true);e.forms??=[];const i=e.forms.findIndex(x=>x.groupId===g.id);if(i<0)e.forms.push(f);else e.forms[i]=f;});api.toast('Species '+slot+' queued. Compile the ROM to install it.');edit();return false;},old?'Update queued form':'Add to ROM export');}
 function abilityBrowser(){const g=group(),rows=g.creature.abilityDesigns;api.modal('Custom ability designs',`<p>Build readable rules and keep them with this Pokémon. These export as a specification for engine implementation; they do not create native battle hooks.</p><div class="smart-actions"><button id="abilityNew" type="button">＋ Ability design</button><button id="abilityBack" type="button">Back to Pokémon</button></div>${rows.map(a=>`<article class="event-step"><b>${esc(a.name)}</b><p>${esc(a.description)}</p><button type="button" data-ability-edit="${a.id}">Edit ${a.rules.length} rules</button><button type="button" data-ability-delete="${a.id}">Delete design</button></article>`).join('')}`);$('#abilityNew').onclick=()=>abilityEdit({id:spriteId(),name:'New ability',description:'',rules:[]});$('#abilityBack').onclick=edit;document.querySelectorAll('[data-ability-edit]').forEach(b=>b.onclick=()=>abilityEdit(rows.find(a=>a.id===b.dataset.abilityEdit)));document.querySelectorAll('[data-ability-delete]').forEach(b=>b.onclick=()=>{saveCollection('abilityDesigns',rows.filter(a=>a.id!==b.dataset.abilityDelete));abilityBrowser();});}
 function abilityEdit(source){const a=structuredClone(source),label=k=>k.replaceAll('_',' '),options=(id,values,value)=>`<select id="${id}">${values.map(k=>`<option value="${k}" ${k===value?'selected':''}>${esc(label(k))}</option>`).join('')}</select>`;api.modal('Ability design',`<label>Name<input id="abilityName" maxlength="40" value="${esc(a.name)}"></label><label>Description<textarea id="abilityDescription" maxlength="1024">${esc(a.description)}</textarea></label><div id="abilityRules"></div><button id="abilityAddRule" type="button">＋ Rule</button><p>Percent values use whole percentages. Stat stages use −6 to +6. Parameter describes the type, stat, weather or status. Native implementation is still required.</p>`,()=>{collect();const rows=[...group().creature.abilityDesigns],i=rows.findIndex(v=>v.id===a.id);if(i<0)rows.push(a);else rows[i]=a;validateCreature({...group().creature,abilityDesigns:rows});saveCollection('abilityDesigns',rows);abilityBrowser();return false;},'Save design');function collect(){a.name=$('#abilityName').value;a.description=$('#abilityDescription').value;a.rules.forEach((r,i)=>Object.assign(r,{when:$('#arWhen'+i).value,condition:$('#arIf'+i).value,effect:$('#arEffect'+i).value,value:+$('#arValue'+i).value,parameter:$('#arParameter'+i).value}));}function draw(){$('#abilityRules').innerHTML=a.rules.map((r,i)=>`<article class="event-step"><label>When${options('arWhen'+i,ABILITY_TRIGGERS,r.when)}</label><label>If${options('arIf'+i,ABILITY_CONDITIONS,r.condition)}</label><label>Then${options('arEffect'+i,ABILITY_EFFECTS,r.effect)}</label>${number('arValue'+i,'Value',r.value,-10000,10000)}<label>Parameter<input id="arParameter${i}" maxlength="80" value="${esc(r.parameter)}"></label><button type="button" data-ar-remove="${i}">Remove rule</button></article>`).join('');document.querySelectorAll('[data-ar-remove]').forEach(b=>b.onclick=()=>{collect();a.rules.splice(+b.dataset.arRemove,1);draw();});}draw();$('#abilityAddRule').onclick=()=>{collect();if(a.rules.length<32){a.rules.push({when:'switch_in',condition:'always',effect:'stat_stage',value:1,parameter:'Attack'});draw();}};}
 async function editGift(old=null,x=0,y=0){try{
  if(!api.session())throw Error('Open the original expansion ROM to edit this gift.');state.context=await gameContext(api.session().reader);
  const gid=old?.creatureGift?.groupId||state.groupId,f=edits()?.forms?.find(f=>f.groupId===gid);if(!f||!profile())throw Error('Add this Pokémon to the native ROM export first.');
  const map=api.map(),prior=old?.runtime?.steps?.find(s=>s.type==='giveMon'),say=old?.runtime?.steps?.find(s=>s.type==='say');
  api.modal(old?'Edit custom Pokémon gift':'Place custom Pokémon gift',`<p><b>${esc(f.name)}</b> · species ${f.slot}. Face this tile and press A to receive the Pokémon. The native engine sends it to the PC when the party is full.</p><label>Name<input id="formGiftName" maxlength="120" value="${esc(old?.title||'Receive '+f.name)}"></label>${number('formGiftLevel','Level',prior?.level||5,1,100)}<label>Dialogue<textarea id="formGiftText" maxlength="4000">${esc(say?.text||'Here is a Pokémon for you!')}</textarea></label><p class="callout">This gift is repeatable each time you interact. One-time flags for these expansion engines are not verified yet. Remove or disable test gifts before sharing your hack.</p><label class="check"><input id="formGiftEnabled" type="checkbox" ${old?.runtime.enabled!==false?'checked':''}> Enabled in ROM export</label>${old?'<button id="formGiftDelete" type="button">Remove gift event</button>':''}`,()=>{
   const level=+$('#formGiftLevel').value;if(!Number.isInteger(level)||level<1||level>100)throw Error('Choose a level from 1–100.');const px=old?.x??x,py=old?.y??y;if(px<0||py<0||px>=map.width||py>=map.height)throw Error('Tap inside the map.');if(!old&&(map.markers.some(n=>n.x===px&&n.y===py)||map.gates?.some(g=>gateLocal(g,px,py))||map.fieldObjects?.some(o=>o.x===px&&o.y===py)))throw Error('Choose a tile away from existing ROM events, gates and HM objects.');
   const text=$('#formGiftText').value.trim();if(text)wrapDialogue(text);const n=old||newEvent(px,py);changed(()=>{Object.assign(n,{title:$('#formGiftName').value.trim()||'Receive '+f.name,creatureGift:{hash:state.context.hash,groupId:gid},runtime:{action:'sequence',trigger:'interact',enabled:$('#formGiftEnabled').checked,blocksMovement:false,steps:[...(text?[{type:'say',text}]:[]),{type:'giveMon',species:f.slot,level,itemId:0}]}});if(!old)map.markers.push(n);});api.mode('move');api.toast('Gift event saved. Compile and play the edited ROM to receive your form.');
  },old?'Save gift':'Place gift');if(old)$('#formGiftDelete').onclick=()=>{changed(()=>map.markers=map.markers.filter(n=>n.id!==old.id));api.close();};
 }catch(e){api.error(e);}}
 function giftAt(x,y){editGift(api.map().markers.find(n=>n.creatureGift&&n.x===x&&n.y===y),x,y);}
 return{state,open,browser,edit,editGift,giftAt};
}
